import{_ as o,o as c,c as d,a3 as n}from"./chunks/framework.qCVWde4n.js";const h=JSON.parse('{"title":"hub：每台设备都是一个 Muse","description":"","frontmatter":{},"headers":[],"relativePath":"zh/hub.md","filePath":"zh/hub.md"}'),a={name:"zh/hub.md"};function s(t,e,r,i,l,p){return c(),d("div",null,[...e[0]||(e[0]=[n(`<h1 id="hub-每台设备都是一个-muse" tabindex="-1">hub：每台设备都是一个 Muse <a class="header-anchor" href="#hub-每台设备都是一个-muse" aria-label="Permalink to &quot;hub：每台设备都是一个 Muse&quot;">​</a></h1><p>在手机、电脑和浏览器上登录同一个 nanoMuse Cloud 账号，它们就能看见彼此。每台设备跑着自己的 Muse，带着自己的手——手机上的 App 和沙箱，电脑上的 shell 和屏幕——其中任何一台都可以从任何网络拜托任何另一台做点什么。网页控制台自己没有手；它是通往其余设备的前门。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>phone ──┐                         ┌── computer (nanoMuse Desktop)</span></span>
<span class="line"><span>        ├──▶  nanoMuse Cloud  ◀───┤</span></span>
<span class="line"><span>web  ───┘        /v1/hub          └── another phone / computer</span></span></code></pre></div><p>每台设备向中继开一条出站的 WebSocket 并一直保持。设备上不监听任何东西，不需要端口转发，也不需要同一个 Wi-Fi；中继只在一个账号的设备之间转发帧，从不看任务里面是什么。添加一台电脑就是这么做的：在上面装 nanoMuse Desktop，用同一个账号登录——不用手动下载什么，也不用输什么码。这也是唯一的入口：那个通过局域网配对的独立主机脚本（0.1.13–0.1.23）已经去掉了，所以手机列表里缺了一台电脑，几乎总是因为它登录的是另一个账号——手机上的 <em>设置 → 电脑</em> 显示手机用的是哪个账号。</p><h2 id="what-you-can-say" tabindex="-1">你可以说什么 <a class="header-anchor" href="#what-you-can-say" aria-label="Permalink to &quot;你可以说什么 {#what-you-can-say}&quot;">​</a></h2><p>在手机上，任何聊天里：</p><ul><li>「在我 Mac 上列一下下载文件夹」——<code>nanomuse-pc ls ~/Downloads --on mac</code></li><li>「让电脑把项目编译一遍，把日志发给我」——<code>nanomuse-pc task &quot;…&quot; --on desk</code></li><li>「电脑截个图给我看」——<code>nanomuse-pc screen --on desk</code></li></ul><p>在电脑上，终端里（<code>nanomuse-desktop</code>）：</p><ul><li>「在我手机上截个图」——<code>device_screen</code></li><li>「让手机的 Muse 把最后一条通知读给我」——<code>delegate</code></li><li>「给手机发个通知：晚饭好了」——<code>device_notify</code></li></ul><p>在网页控制台（<code>/app</code>）里：选一台设备，打字。任务在那台设备的 Muse 上跑；审批以卡片的形式显示在页面里。</p><p>hub 上传递两类请求：</p><ul><li><p><strong>动作</strong>——<code>info</code>、<code>shell</code>、<code>files</code>、<code>file.get</code>、<code>file.put</code>、<code>open</code>、<code>screen</code>、<code>notify</code>。原始、即时。一条 <code>shell</code> 命令在发出之前先在<em>发起方</em>判定，用的和本地命令同一套阶梯（手机的 ShellGuard、桌面的 <code>guard.py</code>）：读取和构建静默放行，删除 / 发送 / 付款 / 系统命令则等发起设备上的审批卡片。</p></li><li><p><strong>任务</strong>——<code>task {text}</code>：用自然语言描述的一整件事，交给目标设备自己的 Muse，在它自己的一个对话里完成。可能要几分钟。那个 Muse 碰到需要审批的事时不会自己拿主意：问题以 <code>event {stage:&quot;approval&quot;}</code> 传回来，发起设备显示它惯常的卡片（手机上是 RiskGate，桌面上是终端提示，网页控制台里是一张卡片）。回答以 <code>approve {approval_id, allow}</code> 传回去。</p><p>任务运行期间，目标设备发送 <code>event</code> 帧，<code>body.stage</code> 告诉发起方该画什么，于是这次运行在发起方的聊天里读起来和在目标设备自己那里一样：工具开始时是 <code>tool {id, name, summary}</code>，结束时是 <code>tool_result {id, name, ok, summary}</code>（同一个 <code>id</code>）；<code>approval {approval_id, preview, risk, reason, device, timeout}</code>，以及任一方作出决定后的 <code>approval_result {approval_id, status}</code>；<code>text {text, interim}</code> 是 Muse 一路上说的话；<code>image</code> 和 <code>file</code> 是它做出来的东西；<code>error</code>。<code>result</code> 帧带着最终答案。</p></li><li><p><strong>编程助手</strong>——<code>coding.agents</code>、<code>coding.sessions</code>、<code>coding.session</code>、<code>coding.send</code>、<code>coding.stop</code>、<code>coding.runs</code>：电脑上的 Cursor / Codex / Claude Code 会话，由那里的运行时从磁盘读取，并通过这些助手自己的 CLI 来驱动。<code>coding.send {agent, text, session_id?, workspace?, wait}</code> 以 <code>event</code> 帧把运行过程流式传回（<code>started</code>、<code>text</code>、<code>tool</code>、<code>done</code>、<code>error</code>，每个都带运行 id，发起方据此可以 <code>coding.stop</code>），最后以完成的运行作答。只有装了这个模块的运行时才会宣告这些动作。<a href="./coding-agents">coding-agents.md</a>。</p></li></ul><p>每台设备自己决定允许别人做什么。<strong>远程控制</strong>关着时（手机：<em>设置 → nanoMuse Cloud → 设备</em>；桌面：<code>set remote_control off</code>），这台设备只回答 <code>info</code>，别的一概不答——它仍然能看见并操纵其他设备。开着时，任何<em>对</em>这台设备做事的原始动作（<code>shell</code>、<code>files</code>、<code>file.get</code>、<code>file.put</code>、<code>open</code>、<code>screen</code>、<code>coding.send</code>、<code>coding.stop</code>）都要先经这台设备旁的人同意：惯常的审批卡片，「允许一次」或「对这台设备总是允许」——后一种长期有效的回答是「权限」下的一条授权（<code>remote_control:&lt;device id&gt;</code>）。旁边没人，卡片过期后发起方听到的是 <code>not_allowed</code>。<code>info</code> 和 <code>notify</code> 从不询问；<code>task</code> 在设备自己的哨兵（Sentinel）之下运行，它的卡片照旧传回发起方。一台设备只能 <code>approve</code> 发给它的、属于它自己发起的运行的卡片——绝不能回答「是否允许它运行某事」的那张卡片。</p><h3 id="proposed-proxy-fetch-—-the-phone-uses-the-computer-s-connection" tabindex="-1">提案：<code>proxy_fetch</code>——手机借用电脑的网络 <a class="header-anchor" href="#proposed-proxy-fetch-—-the-phone-uses-the-computer-s-connection" aria-label="Permalink to &quot;提案：\`proxy_fetch\`——手机借用电脑的网络 {#proposed-proxy-fetch-—-the-phone-uses-the-computer-s-connection}&quot;">​</a></h3><p>还没做；先写在这里，让三个实现在有人动手之前先取得一致。场景：手机的网络连不上 <code>chatgpt.com</code> 或某个服务商的主机（<a href="./own-key#when-the-provider-cannot-be-reached">own-key.md</a> 里的那张卡片），而这个人的电脑连得上。电脑的运行时通过 hub 转发那次服务商调用——只转发那个——像代理一样。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ call   {id, to, action:&quot;proxy_fetch&quot;,</span></span>
<span class="line"><span>          args:{method, url, headers:{…}, body?, stream?}}     body base64; stream: want SSE chunks as events</span></span>
<span class="line"><span>← event  {id, from, body:{stage:&quot;headers&quot;, status, headers:{…}}}</span></span>
<span class="line"><span>← event  {id, from, body:{stage:&quot;chunk&quot;, data}}                data base64; one per SSE chunk when stream is true</span></span>
<span class="line"><span>← result {id, ok:true, body:{status, headers:{…}, data?}}      data base64 when stream was false</span></span>
<span class="line"><span>← result {id, ok:false, error:&quot;not_allowed&quot; | &quot;host_refused&quot; | &quot;too_large&quot; | &quot;upstream&quot;, message}</span></span></code></pre></div><p>让它可以接受的几条规则，每条在提供服务的一方都是一行代码：</p><ul><li><strong>电脑上主动开启。</strong> 桌面插件只在「让我的手机借用这台电脑的网络访问服务商」打开时（<em>设置 → 设备</em>）才在 <code>hello</code> 里宣告 <code>proxy_fetch</code>；关着时，这个动作是 <code>unknown_call</code>。信任级别和 <code>device_shell</code> 相同：这台设备的「远程控制」必须开着，某台设备的第一次调用会弹出惯常的卡片——「允许一次」或「对这台设备总是允许」（一条 <code>remote_control:&lt;device id&gt;</code> 授权）。</li><li><strong>只到指定主机，不是整个互联网。</strong> 电脑只向服务商目录（<code>providers.json</code>）里的主机、<code>chatgpt.com</code> 和 <code>auth.openai.com</code>，以及它自己配置的服务商的自定义 base URL 转发；其余一律 <code>host_refused</code>。绝不转发到中继、局域网地址或 <code>file:</code>。</li><li><strong>请求头照传，秘密不留。</strong> 手机发送自己的 <code>Authorization</code>（套餐的 token、它自己的 key）；电脑原样转发，只记录主机、状态码和大小——从不记录请求头或正文。</li><li><strong>有上限。</strong> 请求正文超过 8 MB、响应单帧超过 <code>HUB_FRAME_LIMIT</code> 都是 <code>too_large</code>；流在十分钟处切断；每台发起设备同一时间只有一个调用。</li><li><strong>手机来选。</strong> 「连不上」的那张卡片只在有一台宣告了 <code>proxy_fetch</code> 的电脑在线时才提供「用我电脑的网络」这个选项；这个选择按服务商实例保存，并在实例上显示为一行，免得有人忘了自己的 key 要经过电脑。</li></ul><p>为什么这次只是设计而不是代码：hub 帧本身很小，但提供服务的一方是电脑上一个新的信任面（一个携带这个人服务商 token 的转发器），而手机的两套 HTTP 栈各自都需要一个传输层，把请求变成帧、再把帧还原成响应——三个实现，加上第四处必须对主机列表取得一致的地方，这一轮的预算老实说盖不住。在此期间，代理设置（<a href="./own-key#when-the-provider-cannot-be-reached">own-key.md</a>）覆盖了常见情形：电脑上开一个代理（Clash、一条 <code>ssh -D</code>），手机指向它。</p><h2 id="frames" tabindex="-1">帧 <a class="header-anchor" href="#frames" aria-label="Permalink to &quot;帧 {#frames}&quot;">​</a></h2><p><code>WS /v1/hub</code> 上的 JSON 文本帧，<code>Authorization: Bearer nm_…</code>（浏览器则把 key 放在 <code>hello</code> 里）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>→ hello    {device:{id,name,kind,os,version,actions[]}}     kind: phone | computer | web</span></span>
<span class="line"><span>← welcome  {device_id, devices:[…], server:{version,frame_limit,time}}</span></span>
<span class="line"><span>← devices  {devices:[{id,name,kind,os,version,online,last_seen,controllable}]}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ call     {id, to, action, args}</span></span>
<span class="line"><span>← call     {id, from:{id,name,kind}, action, args}          (delivered to the target)</span></span>
<span class="line"><span>→ event    {id, body}          ← event  {id, from, body}    progress, approvals, images</span></span>
<span class="line"><span>→ result   {id, ok, body | error, message}                  ← result (to the caller)</span></span>
<span class="line"><span>← error    {code, message, id?}   device_offline · not_controllable · self_call · unknown_call · too_large · bad_frame</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ devices  {}        → rename {name}        → forget {device_id}        → ping  ← pong</span></span>
<span class="line"><span>← profile  {rev, device}       the account&#39;s name, look or connectors changed (PUT /v1/me/profile); fetch it</span></span>
<span class="line"><span>← sync     {what:&quot;conversations&quot;, cursor, from}   another device pushed or deleted synced conversations; pull /v1/sync/changes</span></span>
<span class="line"><span>← working  {cid, from, device_name, working, at}  another device started (true) or finished (false) a turn in that synced conversation</span></span></code></pre></div><p>关闭码：<code>4000</code> 期待 hello、<code>4001</code> key 无效、<code>4002</code> 设备无效、<code>4003</code> 被同一设备 id 的更新连接顶替——或者，带原因 <code>hub_paused</code>（中继 0.22）时，是运营者关掉了 hub 或整个服务：客户端应等一会儿再重连，而不是立刻重试（<a href="./cloud#controls">cloud.md › 控制</a>）。</p><p>设备 id 按安装生成（<code>phone-…</code>、<code>pc-…</code>）；名字是给人看的，可以在设备上改。<code>web</code> 设备从不作为目标，也不会被记住。<code>file.get</code>、<code>file.put</code> 和 <code>screen</code> 的正文以 base64 携带字节（<code>data</code>）并附 <code>mime</code>；桌面拒绝超过 8 MB 的文件，中继拒绝超过 <code>HUB_FRAME_LIMIT</code> 的帧。</p><p>智能体的名字和形象属于账号，不属于某台设备：中继上的 <code>GET</code> / <code>PUT /v1/me/profile</code> 保存它们（小龙、某个颜色底上的 emoji，或者形象工作室里画的一张形象及其五张小图），后写的胜出，一个 <code>profile</code> 帧通知其他设备去取新的 <code>rev</code>。运行时在 <code>nanomuse/hub/profile.py</code> 里做这件事，手机在 <code>io.github.nanomuse.cloud.ProfileSync</code> 里做；写入的那台设备会跳过自己的回声。</p><p>同一份 profile 还带着<strong>哪台设备连接了什么</strong>（0.1.34）：一个 <code>connectors</code> 列表，每一项有连接器的 id 和标签、有地址的话还有地址、登录方式（<code>oauth</code>、<code>key</code> 或 <code>open</code>）、设备的名字和 id、是否启用，以及时间。一台设备只写自己持有的那些项；中继保留其他设备的项，列表上限 64 项，并拒绝任何带有 token、secret、key、authorization 或 password 字段的项——凭据绝不离开登录它的那台设备。其他设备在连接器目录下把这些项列为「已在 &lt;device&gt; 上连接——在这里登录即可在这台设备上使用」，照常的本地登录就是对应的操作。</p><p>0.1.36 起，<strong>对话</strong>也会跟着走，但走的是另一条路：它们的文本经 REST（<code>/v1/sync/*</code>，<a href="./cloud#conversation-sync">cloud.md</a>）进入中继的同步存储，hub 只负责捎个信。中继接受了一次推送之后，或者一次删除之后，账号的每一条<em>其他</em>套接字都会收到 <code>sync {what:&quot;conversations&quot;, cursor, from}</code>——<code>cursor</code> 是变更后账号的计数器，<code>from</code> 是做出变更的设备 id——然后从自己的游标开始拉取新内容。在 <code>from</code> 里看到自己 id 的设备忽略这一帧。0.1.38 起（中继 0.20），hub 还带着<strong>谁在回答</strong>：一台设备在某个同步对话里开始或结束一轮时，会 POST <code>/v1/sync/working</code>，其他套接字收到 <code>working {cid, from, device_name, working, at}</code>——各个 App 在最后一条消息下面显示「kwai 正在处理…」，直到 <code>working: false</code> 到来、回复本身到达，或者过了十分钟。中继只在内存里保留这些。默认只同步主要聊天；旁聊只在打开了「同时同步旁聊」的设备之间来往。其他什么都不同步——key、服务商和设置留在输入它们的地方，文件和图片留在生成它们的设备上。各个 App 怎么用它，见 <a href="./every-device#the-same-conversations-everywhere">every-device.md</a>。</p><h2 id="the-code" tabindex="-1">代码 <a class="header-anchor" href="#the-code" aria-label="Permalink to &quot;代码 {#the-code}&quot;">​</a></h2><p>各设备的 App 怎样围绕这些帧搭起来——设备页、发给某台设备的旁聊、两端都能回答的审批、电脑自己的手——在 <a href="./every-device">every-device.md</a> 里。</p><ul><li>中继：<a href="https://github.com/nano-muse/nanoMuse/blob/main/cloud/nanomuse_cloud/hub.py" target="_blank" rel="noreferrer"><code>cloud/nanomuse_cloud/hub.py</code></a>——按账号的注册表、路由、<code>GET /v1/devices</code>、<code>DELETE /v1/devices/{id}</code>；控制台在 <a href="https://github.com/nano-muse/nanoMuse/tree/main/cloud/nanomuse_cloud/console/" target="_blank" rel="noreferrer"><code>cloud/nanomuse_cloud/console/</code></a> 下。</li><li>Android：<code>io.github.nanomuse.hub</code>——<code>HubClient</code>（OkHttp，重连）、<code>Hub</code>（状态、偏好、<code>call</code>/<code>find</code>）、<code>HubActions</code>（手机替别人做的事，包括通过无界面聊天运行器执行的 <code>task</code>）、<code>HubService</code>（前台服务，<code>remoteMessaging</code>）。<code>nanomuse-pc</code>（<code>io.github.nanomuse.reach</code>）从手机的沙箱 shell 访问 hub 上的设备。</li><li>运行时（带窗口的桌面版，<code>nanomuse serve</code>）：<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/cloud.py" target="_blank" rel="noreferrer"><code>nanomuse/cloud.py</code></a>（账号）、<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/hub/client.py" target="_blank" rel="noreferrer"><code>nanomuse/hub/client.py</code></a>（套接字、重连）、<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/hub/actions.py" target="_blank" rel="noreferrer"><code>nanomuse/hub/actions.py</code></a>（这台电脑替别人做的事）、<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/hub/service.py" target="_blank" rel="noreferrer"><code>nanomuse/hub/service.py</code></a>（收到的 <code>task</code> 放进一个可见的旁聊，<code>tool</code>/<code>tool_result</code>/<code>approval</code>/<code>approval_result</code> 各阶段双向传递，设备线程）、<a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/tools/devices.py" target="_blank" rel="noreferrer"><code>nanomuse/tools/devices.py</code></a>（<code>devices</code>、<code>device_*</code>、<code>delegate</code>）；<code>/api/cloud/*</code> 和 <code>/api/hub/*</code> 在 <a href="https://github.com/nano-muse/nanoMuse/blob/main/nanomuse/server/api.py" target="_blank" rel="noreferrer"><code>nanomuse/server/api.py</code></a>。测试：<code>tests/test_hub.py</code>，用一个假中继。</li><li>网页版：<code>DevicesScreen</code>、设备聊天和转发过来的审批卡片，在 <a href="https://github.com/nano-muse/nanoMuse/tree/main/web/src/" target="_blank" rel="noreferrer"><code>web/src/</code></a>——见 <a href="./every-device">every-device.md</a>。</li></ul><h2 id="trust" tabindex="-1">信任 <a class="header-anchor" href="#trust" aria-label="Permalink to &quot;信任 {#trust}&quot;">​</a></h2><p>中继用账号 key 验证每一条套接字，并且只在账号内部路由；它存设备名和最后在线时间，不存问了什么。一台设备只回答自己账号的设备，而且只在它的「远程控制」开关开着时——对于任何会在那里运行、读取或写入的事，还要那台设备旁的人同意过（一次，或对发起设备总是允许）。命令在输入它的地方判定，然后才发出；远端 Muse 的审批由发起的人回答，绝不由另一个 Muse 回答。在一台设备上退出登录会在中继吊销那台设备的 key，并把它从 hub 上摘下来；手机和控制台的「设备」列表显示所有登录过的设备，所以你不认识的设备是看得见的，等它离线后「移除」就能把它去掉。</p>`,32)])])}const m=o(a,[["render",s]]);export{h as __pageData,m as default};
